import{t as e}from"./jsx-runtime-lw2jiZar.js";import{B as t,C as n,E as r,M as i,N as a,O as o,P as s,T as c,_ as l,b as u,j as d,k as f,p,v as m,w as h,x as g}from"./shared-C5BCElVa.js";import{t as _}from"./folder-git-2-CZqyCk4j.js";import{t as v}from"./search-f2spAuW6.js";import{n as y,t as b}from"./lesson-17-task-add-flow-aakQRCku.js";var x=e();function S({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{variant:`project`,chip:e??`Блок 4 · Console Planner`,title:`Практика: Planner`,intro:`Проверим готовый Planner, объясним путь данных и безопасно изменим знакомое представление.`,tags:[{icon:(0,x.jsx)(t,{size:14}),label:`проверка поведения`},{icon:(0,x.jsx)(v,{size:14}),label:`путь данных`},{icon:(0,x.jsx)(_,{size:14}),label:`проверенная история`}]}),(0,x.jsxs)(s,{number:`00`,title:`От проверенной передачи к самостоятельной правке`,children:[(0,x.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`В предыдущем занятии мы получили отдельную копию опубликованного Planner, создали для неё окружение и проверили запуск по README.`},{title:`Новый вопрос`,description:`Как доказать, что мы понимаем готовую программу, и изменить её вид, не меняя правила работы и данные?`},{title:`Результат`,description:`Полный сценарий подтверждает поведение, разбор функций объясняет путь задачи, а правка format_task() меняет только отображение.`}]}),(0,x.jsx)(`p`,{children:`Раньше мы по частям создавали и проверяли команды Planner. Независимый запуск подтвердил, что опубликованная версия не зависит от файлов исходной папки. Теперь используем готовый результат как целое: сначала сверяем поведение, затем прослеживаем ответственность знакомых функций и выполняем одну небольшую правку. Следующая глава получит тот же проект и его проверенную историю, а не новую заготовку.`}),(0,x.jsx)(r,{tone:`info`,children:`Наша цель здесь не добавить ещё одну команду. Мы проверим уже существующие возможности и изменим только подпись карточки.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Проверяем поведение, а не снимок экрана`,children:[(0,x.jsx)(o,{children:`Проверка начинается с ожидания: называем исходное состояние, действие, ожидаемое изменение и ответ интерфейса, а затем сравниваем их с запуском. Так мы замечаем и верный ответ, и данные, которые могли измениться после отказа.`}),(0,x.jsx)(`p`,{children:`Представим маршрут с несколькими контрольными пунктами. Отметка на последнем пункте не доказывает, что мы прошли предыдущие: нужно сверить весь маршрут. Так же один удачный вывод не подтверждает работу всего Planner. Мы проверим пустой список, создание задачи, её повторный просмотр, поиск, смену статуса, статистику и штатное завершение.`}),(0,x.jsx)(p,{prompt:`Свяжем действие с наблюдаемым результатом каждой проверки.`,leftTitle:`Действие`,rightTitle:`Что проверяем`,pairs:[{left:(0,x.jsx)(`code`,{children:`add`}),right:(0,x.jsx)(x.Fragment,{children:`Список увеличился на одну запись`})},{left:(0,x.jsx)(`code`,{children:`find`}),right:(0,x.jsx)(x.Fragment,{children:`Найденная запись показана без изменения`})},{left:(0,x.jsx)(`code`,{children:`done`}),right:(0,x.jsx)(x.Fragment,{children:`Изменён выбранный статус, соседние записи целы`})},{left:(0,x.jsx)(`code`,{children:`stats`}),right:(0,x.jsx)(x.Fragment,{children:`Итог совпадает с числом записей и их флагами`})}],explanation:`Наблюдение связывает входное действие с состоянием до и после. Мы также проверяем отказ и отсутствие побочного изменения.`}),(0,x.jsx)(`p`,{children:`Для добавления фиксируем исходную длину списка, ввод и новую карточку. Для ошибки ввода проверяем, что задача не появилась. Для завершения важны выбранный id и сохранность соседней карточки. Сценарий становится проверяемым, когда результат можно пересчитать или сравнить, а не только оценить по внешнему виду.`})]}),(0,x.jsxs)(s,{number:`02`,title:`Прослеживаем путь одной задачи`,children:[(0,x.jsx)(`p`,{children:`Команда add связывает знакомые части программы в определённом порядке. Ввод сначала проверяется, потому что фабрика должна получить полный допустимый набор значений, а общий список должен измениться только после проверки.`}),(0,x.jsx)(`p`,{children:`Путь похож на передачу посылки через несколько рабочих мест: приёмщик проверяет адрес, сборщик оформляет содержимое, журнал отмечает принятую посылку, а принтер выпускает наклейку. В Planner ввод играет роль приёмки, проверка полей отсеивает отказ, фабрика создаёт словарь, общий список принимает запись, а функция format_task() возвращает строку. Это только аналогия: функции передают значения и ссылки на объекты, а не физическую коробку.`}),(0,x.jsxs)(`figure`,{className:`lesson-infographic lesson-infographic--lesson17`,children:[(0,x.jsxs)(`picture`,{children:[(0,x.jsx)(`source`,{media:`(max-width: 640px)`,srcSet:y}),(0,x.jsx)(`img`,{src:b,alt:`Проверенные title и priority и текущий список поступают в операцию добавления. Она назначает id, создаёт одну карточку, добавляет её в тот же список и возвращает для форматирования и показа.`,width:1672,height:836,loading:`lazy`,decoding:`async`})]}),(0,x.jsx)(`figcaption`,{children:`Операция меняет общий список и возвращает ту же новую карточку для подтверждения.`})]}),(0,x.jsx)(`p`,{children:`Схема показывает два результата одного вызова: прежний список получает новую запись, а та же возвращённая карточка передаётся в format_task() для показа. Ветка к tasks обозначает изменение единственного списка; форматирование и печать не создают второй записи.`}),(0,x.jsx)(h,{title:`Прослеживаем добавление`,prompt:`Соберём порядок действий обработчика добавления. Один фрагмент относится к другой работе.`,pieces:[{id:`read`,code:`Получаем команду и поля через input()`},{id:`validate`,code:`Проверяем команду, title и priority`},{id:`id`,code:`Получаем следующий id`},{id:`create`,code:`Создаём словарь через create_task()`},{id:`append`,code:`Добавляем одну запись в tasks`},{id:`show`,code:`Передаём запись в format_task() и показываем строку`},{id:`success`,code:`Печатаем успех до добавления записи`}],correctOrder:[`read`,`validate`,`id`,`create`,`append`,`show`],explanation:`До проверки полей запись не создаём. После проверки фабрика готовит полный словарь, список меняется один раз, а format_task() создаёт строку для показа.`,incorrectExplanation:`Мы подтверждаем добавление только после append. Сообщение об успехе до этого шага обещало бы результат, которого ещё нет в списке.`}),(0,x.jsx)(`p`,{children:`Внутри проекта меню управляет сценарием, обработчик связывает ввод с операциями, а отдельные функции выполняют знакомые правила. create_task() собирает поля, но не выбирает пункт меню. add_task() меняет общий список, но не решает, какие данные спросить. format_task() возвращает представление одной записи, а вызывающая сторона решает, когда вызвать print(). Такое разделение помогает найти место для небольшой правки и не дублировать одну обязанность.`}),(0,x.jsx)(g,{question:`Что должно произойти с tasks, если проверка приоритета отклонила ввод?`,hint:`Проверим, дошёл ли обработчик до создания и добавления словаря.`,answer:(0,x.jsx)(`p`,{children:`Мы не создаём и не добавляем новую запись. После исправления значения продолжаем тот же запрос, а уже принятые карточки остаются в прежнем порядке.`})})]}),(0,x.jsxs)(s,{number:`03`,title:`Объясняем функцию через вход, результат и эффект`,children:[(0,x.jsx)(o,{children:`Имя функции ещё не объясняет, как она работает. Для выбранной операции называем аргументы, результат, возможное изменение общего состояния и место, где появляется сообщение. Так мы проверяем причинную цепочку, а не просто перечисляем знакомые слова.`}),(0,x.jsx)(`p`,{children:`find_task(tasks, task_id) получает список и id. Она возвращает найденный словарь или None, когда совпадения нет, и сама не меняет список. Возвращённый словарь при этом является той же записью, что лежит внутри списка. Поэтому другая функция может изменить его поле, если получила эту ссылку.`}),(0,x.jsx)(`p`,{children:`mark_task_done() использует поиск, сначала обрабатывает отсутствие записи, затем устанавливает is_done в True и возвращает логический результат. Возврат не отменяет побочный эффект: функция может одновременно сообщить об успехе и изменить найденный словарь. Печать остаётся отдельным действием обработчика. Повторное присваивание True не переключает карточку обратно.`}),(0,x.jsx)(m,{code:`tasks = [{"id": 7, "is_done": False}]
found = tasks[0]
if found is not None:
    found["is_done"] = True
    result = True`,steps:[{line:0,note:`В списке находится один словарь; его статус пока False.`,vars:{"tasks[0].is_done":`False`}},{line:1,note:`found получает ссылку на тот же словарь, а не его отдельную копию.`,vars:{found:`tasks[0]`}},{line:2,note:`Проверяем, что поиск вернул запись. Если бы результатом был None, к полю не обращались бы.`},{line:3,note:`Меняем поле общего словаря через найденную ссылку.`,vars:{"tasks[0].is_done":`True`}},{line:4,note:`Затем записываем результат операции. Это значение отдельно от побочного эффекта.`,vars:{result:`True`}}]}),(0,x.jsx)(n,{code:`task = find_task(tasks, task_id)
task["is_done"] = True
print(format_task(task))`,question:`Какой случай приводит к ошибке до показа карточки?`,options:[`Поиск вернул None для отсутствующего id`,`В списке находится выполненная задача`,`format_task() вернула строку`],correctIndex:0,explanation:`Для отсутствующего id find_task() возвращает None. До чтения поля нужна проверка. При отказе функция должна вернуть неуспех и оставить список неизменным.`,fix:`task = find_task(tasks, task_id)
if task is None:
    return False
task["is_done"] = True
print(format_task(task))`}),(0,x.jsx)(`p`,{children:`Ошибочный пользовательский ввод, неизвестный id и программный дефект означают разные вещи. При неправильном тексте или диапазоне программа повторяет запрос. При положительном id без совпадения операция сообщает, что запись не найдена. Обращение к полю у None уже является дефектом в коде: текст traceback (трассировки ошибки Python) помогает локализовать его, а проверка до изменения предотвращает сбой.`}),(0,x.jsx)(`p`,{children:`build_statistics() читает текущие записи и их флаги, затем возвращает сводные значения. Она не добавляет отдельный список выполненных задач и не меняет исходные карточки. При двух записях, одна из которых выполнена, проверяем total = 2, completed = 1, left = 1 и 50 процентов. Повторное завершение не создаёт третью запись и не меняет эту сводку.`}),(0,x.jsx)(p,{prompt:`Соотнесём части контракта функции с тем, что мы проверяем.`,pairs:[{left:(0,x.jsx)(x.Fragment,{children:`Аргументы`}),right:(0,x.jsxs)(x.Fragment,{children:[(0,x.jsx)(`code`,{children:`tasks`}),` и `,(0,x.jsx)(`code`,{children:`task_id`})]})},{left:(0,x.jsx)(x.Fragment,{children:`Возврат`}),right:(0,x.jsxs)(x.Fragment,{children:[`Словарь записи либо `,(0,x.jsx)(`code`,{children:`None`})]})},{left:(0,x.jsx)(x.Fragment,{children:`Эффект поиска`}),right:(0,x.jsx)(x.Fragment,{children:`Список не меняется`})},{left:(0,x.jsx)(x.Fragment,{children:`Эффект завершения`}),right:(0,x.jsxs)(x.Fragment,{children:[`Меняется `,(0,x.jsx)(`code`,{children:`is_done`}),` найденной записи`]})}],explanation:`Контракт помогает отличить функцию чтения от операции, которая меняет общий словарь.`})]}),(0,x.jsxs)(s,{number:`04`,title:`Меняем представление, сохраняя запись`,children:[(0,x.jsx)(`p`,{children:`Небольшая правка должна менять ровно выбранную обязанность. В финальном шаге это формат строки, а не структура словаря, поиск, диапазон приоритета или поведение статуса.`}),(0,x.jsx)(`p`,{children:`Представим бумажную наклейку на коробке. На ней видны номер, название, приоритет и состояние, но замена наклейки не меняет содержимое. В Planner словарь остаётся данными, а format_task() создаёт читаемую строку. Строка не становится вторым источником состояния: замена текста не должна присваивать новое значение is_done.`}),(0,x.jsx)(l,{code:`parcel = {"city": "Тверь", "fragile": True}

def parcel_label(parcel):
    if parcel["fragile"]:
        kind = "осторожно"
    else:
        kind = "обычно"
    return f'{parcel["city"]}: {kind}'

before = parcel.copy()
print(parcel_label(parcel))
print(parcel == before)`,output:`Тверь: осторожно
True`,hint:`Функция читает поля и возвращает строку. Меняет ли она сам словарь?`}),(0,x.jsx)(`p`,{children:`Функция читает поля и возвращает строку; словарь после вызова равен копии. Аналогия с наклейкой объясняет разницу между представлением и записью, но не означает, что программа может надёжно восстановить словарь из произвольной строки.`}),(0,x.jsx)(`p`,{children:`На карточке Planner функция format_task() показывает четыре смысла: id, title, priority и состояние. Мы меняем только понятную подпись открытого состояния; значение is_done остаётся логическим флагом. Та же функция вызывается после добавления, в общем просмотре, при поиске по id и при поиске по названию. Если эти места форматируют запись по-разному, небольшой текст пришлось бы исправлять в нескольких обработчиках. Результирующая строка является отдельным значением. Мы меняем её текст без присваивания полям словаря; если функция изменит словарь, это уже побочный эффект, который проверяем отдельно.`}),(0,x.jsx)(c,{question:`Как изменить подпись во всех командах и не дублировать форматирование?`,left:{title:`Собирать строку в каждом обработчике`,code:`print(f"#{task['id']} {task['title']}")`,note:`Разные команды могут начать показывать карточку по-разному.`},right:{title:`Использовать одну функцию format_task()`,code:`def format_task(task):
    if task["is_done"]:
        status = "выполнена"
    else:
        status = "не завершена"
    return f"#{task['id']} {task['title']} · {status}"`,note:`Одна функция отвечает за представление карточки во всех командах.`},preferred:`right`,explanation:`Функция format_task() создаёт строку одной карточки. Состояние и выбор команды остаются у других функций; одна правка вида применяется во всех существующих командах.`}),(0,x.jsx)(`p`,{children:`До изменения записываем ожидаемый результат для открытой и выполненной карточек. Обе должны сохранить id, title и priority, а отличаться только показанным состоянием. При проверке сравниваем строку, исходные значения, длину списка и его порядок. Так мы отделяем изменение отображения от изменения данных.`})]}),(0,x.jsxs)(s,{number:`05`,title:`Повторяем старые гарантии и сохраняем изменение`,children:[(0,x.jsx)(`p`,{children:`Регрессия возникает, когда новая правка ломает то, что раньше работало. После правки format_task() проверяем новую подпись в add, list, find и search, а затем повторяем знакомые сценарии ввода, статусов и статистики. Полная регрессионная проверка не означает повторную сборку проекта: мы проходим готовый сценарий и отдельно проверяем команды, которые вызывают format_task().`}),(0,x.jsx)(`p`,{children:`Одной удачной строки мало. Проверяем обе ветки состояния, повторное завершение, неизвестный id, пустой поиск и сохранность названия с пользовательским регистром. Количество карточек, их порядок и числовая сводка должны остаться прежними. Если поведение разошлось, записываем вход, ожидание и факт, воспроизводим причину и только затем меняем код.`}),(0,x.jsxs)(`p`,{children:[`Поиск и сводка отвечают на разные вопросы. Поиск выбирает для показа подходящие названия, но не удаляет остальные записи из общего списка `,(0,x.jsx)(`code`,{children:`tasks`}),`. `,(0,x.jsx)(`code`,{children:`stats`}),` считает все задачи, включая те, которые не подошли текущему запросу. После `,(0,x.jsx)(`code`,{children:`done`}),` мы проверяем изменённую карточку через `,(0,x.jsx)(`code`,{children:`find`}),` и `,(0,x.jsx)(`code`,{children:`search`}),`, а затем сверяем сводку по всему списку. Полные счётчики и остальные записи должны сохраниться. Значение `,(0,x.jsx)(`code`,{children:`total`}),` не уменьшается из-за поиска: фильтр результата не меняет модель. Поиск помогает найти запись, но не становится новым источником состояния.`]}),(0,x.jsx)(u,{question:`Что доказывает чистый git status после правки format_task()?`,options:[`Что поиск по отсутствующему id не меняет список`,`Что файлы совпадают с последним коммитом`,`Что все команды Planner прошли полный сценарий`],correctIndex:1,explanation:`Git показывает состояние файлов относительно истории. Поведение поиска подтверждаем запуском и сравнением данных.`}),(0,x.jsx)(`p`,{children:`git diff показывает незаписанные изменения, а git diff --cached помогает отдельно осмотреть подготовленный снимок. После проверки нужных файлов создаём коммит в прежнем репозитории и отправляем его в уже настроенный remote. Новую историю через git init не начинаем и проверочную копию не превращаем во второй основной каталог.`}),(0,x.jsx)(r,{tone:`warn`,children:`Коммит и push сохраняют и передают файлы программы, но не карточки tasks, которые существовали только в завершившемся процессе.`}),(0,x.jsx)(`p`,{children:`Если правка меняет пример вывода в README, обновляем только эту строку, чтобы инструкция не расходилась с программой. Полное описание проекта не переписываем: цель занятия в том, чтобы изменить знакомое представление и подтвердить прежние гарантии.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Различаем программу и данные одного запуска`,children:[(0,x.jsx)(`p`,{children:`После штатного exit завершается процесс. Здесь процесс означает работающую копию программы с её текущими значениями в памяти. При новом запуске tasks создаётся заново, поэтому пустой список не означает потерю исходников, коммита или истории.`}),(0,x.jsx)(`p`,{children:`Код в main.py и Git-история остаются на диске. Задачи, которые существовали лишь в памяти процесса, не восстанавливаются. Мы ожидаем пустой просмотр и нулевую статистику после перезапуска и не объявляем сохранение состояния, которого в проекте пока нет. Новое файловое хранилище не добавляем.`}),(0,x.jsx)(g,{question:`Что мы передадим следующей главе после завершения процесса?`,hint:`Отделим файлы и историю проекта от списка, существовавшего только в памяти.`,answer:(0,x.jsx)(`p`,{children:`Мы передаём тот же проверенный проект, README и коммит. Временные записи процесса в Git не попали. В следующей главе сначала сравним поведение с исходной версией, затем безопасно переработаем существующий код.`})}),(0,x.jsx)(`p`,{children:`В Foundations этим завершается проектный маршрут. Следующее занятие отдельного курса Python глубже использует Console Planner как исходную версию для аудита и плана конкретной переработки. Здесь мы проверяем и передаём результат; будущую переработку не начинаем.`})]}),(0,x.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Практика продолжает тот же опубликованный Planner и связывает проверку поведения, объяснение кода, локальную правку и сохранение результата.`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Подтвердим готовую версию`,description:`Сверим README, основной каталог и историю; полный сценарий даст наблюдаемые результаты семи команд и отказных случаев.`},{title:`Объясним причинный путь`,description:`Проследим создание задачи и назовём входы, возвраты, изменения списка и место печати для выбранных функций.`},{title:`Изменим одно представление`,description:`Поменяем подпись в format_task(); обе карточки сохранят четыре поля, а все команды покажут единый новый текст состояния.`},{title:`Проверим и передадим`,description:`Повторим сценарии и сравним данные; diff покажет проверенную правку, а новый запуск начнётся с пустого списка.`}]}),(0,x.jsx)(`p`,{children:`Практика проходит в основном каталоге и продолжает существующий продукт. Мы меняем одну обязанность общей функции форматирования, поэтому проверяем её через add, list, find и search, а отдельно подтверждаем, что статистика по-прежнему читает весь список.`}),(0,x.jsx)(`p`,{children:`Результат передаём следующей главе вместе с прежней историей и пониманием границы хранения: программа и Git сохраняют код, а временные задачи живут только в текущем процессе.`}),(0,x.jsx)(d,{text:`Проверим Planner, проследим путь задачи и изменим только её отображение.`})]})]})}export{S as Lesson20};